// Literal port of the team's Casa3DSDK (module lot/perimeter). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installLotPerimeter(K: Kernel, shared: Shared): void {
  const { EPS, boxC, bx, colorOf, cursor, freeSpans, pieceRecord } = K;
  const makeApi = (...a: any[]): any => K.makeApi(...a);
  const sh = (...a: any[]): any => K.sh(...a);
  function perimeter() {
    const R = shared.ctx.r, lt = R.lot, C = shared.ctx.colors; if (!lt) return; cursor.group = 'lot';
    const rnd = (() => { let s = 99; return () => (s = (s * 16807) % 2147483647) / 2147483647; })();
    const api = makeApi();
    for (const s of lt.perimeter) {
      const alongU = Math.abs(s.v1 - s.v0) < EPS, L = alongU ? s.v0 : s.u0, a = Math.min(alongU ? s.u0 : s.v0, alongU ? s.u1 : s.v1), b = Math.max(alongU ? s.u0 : s.v0, alongU ? s.u1 : s.v1);
      cursor.pc = pieceRecord('lot_wall:' + s.id, s.type === 'wall' ? 'brick' : s.type === 'fence' ? 'wood_soft' : 'steel', null, { tags: ['wall'] });
      const th = s.thickness || 0.15, h = s.height, color = colorOf(s.color) != null ? colorOf(s.color) : (C.wall || 0xb8b4aa), len = b - a;
      const B = (mat, u0, y0, u1, y1, t, c, off = 0) => alongU ? bx(mat, u0, y0, L + off - t / 2, u1, y1, L + off + t / 2, c) : bx(mat, L + off - t / 2, y0, u0, L + off + t / 2, y1, u1, c);
      const col = { type: 'lot_wall', f: -1, x0: alongU ? a : L - th / 2, z0: alongU ? L - th / 2 : a, x1: alongU ? b : L + th / 2, z1: alongU ? L + th / 2 : b }; shared.ctx.colliders.push(col);
      if (s.type === 'wall') { B('plaster', a, 0, b, h, th, color); B('plaster', a, h, b, h + 0.05, th + 0.06, sh(color, 1.15)); }
      else if (s.type === 'fence') {
        const np = Math.max(2, Math.round(len / 2.4) + 1);
        for (let k = 0; k < np; k++) { const u = a + k * len / (np - 1); B('wood', u - 0.04, 0, u + 0.04, h, 0.08, 0x6a5a48); }
        B('screen', a, 0.1, b, h - 0.05, 0.01, 0xb8bcc0); B('metal', a, h - 0.05, b, h, 0.03, 0x8a8e92); B('metal', a, 0.08, b, 0.12, 0.03, 0x8a8e92);
      } else { // iron grille on a low wall
        const gc = C.gate != null ? C.gate : 0x2a2a2e, mh = 0.5;
        B('plaster', a, 0, b, mh, th, color); B('plaster', a, mh, b, mh + 0.04, th + 0.05, sh(color, 1.15));
        const n = Math.max(2, Math.round(len / 0.13)); for (let k = 0; k <= n; k++) { const u = a + k * len / n; B('metal', u - 0.012, mh + 0.04, u + 0.012, h, 0.025, gc); }
        B('metal', a, h - 0.06, b, h - 0.03, 0.04, gc); B('metal', a, mh + 0.1, b, mh + 0.13, 0.04, gc);
      }
      // top
      const top = s.top, ym = h + (s.type === 'wall' ? 0.05 : 0); cursor.pc = null;
      if (top === 'glass') { const cs = [0x2f7a4f, 0x8a5a2a, 0xe8eef0, 0x3a6aa0, 0x4f9a5f]; for (let u = a + 0.05; u < b - 0.03; u += 0.07 + rnd() * 0.04) { const hh = 0.07 + rnd() * 0.09, c = cs[(rnd() * cs.length) | 0], angle = (rnd() - 0.5) * 0.7; boxC('plain', alongU ? u : L + (rnd() - 0.5) * th * 0.6, ym + hh / 2, alongU ? L + (rnd() - 0.5) * th * 0.6 : u, 0.035, hh, 0.02, c, alongU ? 0 : 0, rnd() * 3, angle); } }
      else if (top === 'razor_wire' || top === 'barbed_wire') { // R63: where the house meets the lot wall the wire crossed the room's wall; cuts the stretch and closes each end with a post
        const frees = freeSpans(alongU, L, a, b), high = top === 'razor_wire' ? 0.46 : 0.4;
        for (const [x0, x1] of frees) {
          const w2 = x1 - x0, cm = (x0 + x1) / 2;
          const M = top === 'razor_wire' ? { x: alongU ? cm : L, z: alongU ? L : cm, ry: alongU ? 0 : K.PE, w: w2, d: 0.4, h: 0.4, y: ym, base: 0, floor: -1, colors: C, seed: s.id } : { x: alongU ? cm : L, z: alongU ? L : cm, ry: alongU ? 0 : K.PE, w: w2, d: 0.1, h: 0.3, y: 0, base: ym, floor: -1, colors: C, seed: s.id };
          try { shared.ctx.mv.builders[top](M, api); } catch (e) { console.warn(e); }
          for (const [e, cutOff] of [[x0, x0 > a + 0.01], [x1, x1 < b - 0.01]]) if (cutOff) { B('metal', e - 0.025, ym, e + 0.025, ym + high, 0.05, 0x55585c); B('metal', e - 0.04, ym + high, e + 0.04, ym + high + 0.025, 0.08, 0x3a3c40); }
        }
      }
      else if (top === 'railing') { const gc = C.gate != null ? C.gate : 0x2a2a2e, n = Math.max(2, Math.round(len / 0.14)); for (let k = 0; k <= n; k++) { const u = a + k * len / n; B('metal', u - 0.012, ym, u + 0.012, ym + 0.3, 0.025, gc); B('metal', u - 0.02, ym + 0.3, u + 0.02, ym + 0.38, 0.03, gc); } B('metal', a, ym + 0.08, b, ym + 0.11, 0.03, gc); }
    }
  }
  // SDK paths (lot.paths): paving from the gate to the door; comes over the zone floors (lawn 0.02, ceramic 0.035)
  function paths() {
    const lt = shared.ctx.r.lot; if (!lt || !lt.paths) return; cursor.group = 'lot';
    for (const c of lt.paths) {
      if (c.type === 'vehicle' && c.id !== 'cargo_path') continue; // the garage space already comes paved by the zone
      const color = c.type === 'pedestrian' ? 0xcfcac0 : 0xb4b0a8;
      for (const [u0, v0, u1, v1] of c.rects) {
        bx('sidewalk', u0, 0.0, v0, u1, 0.05, v1, color);
      }
    }
  }
  Object.assign(K, { perimeter, paths });
}
